// Account connection is separate from explicit message and devnet transaction approval.
let connectedWallet=null;
const walletProviders={
  phantom:{name:'Phantom',site:'https://phantom.com/download',color:'#ab9ff2',symbol:'P',get:()=>window.phantom?.solana?.isPhantom?window.phantom.solana:window.solana?.isPhantom?window.solana:null},
  solflare:{name:'Solflare',site:'https://www.solflare.com/download/',color:'#f5a339',symbol:'S',get:()=>window.solflare?.isSolflare?window.solflare:null}
};
function updateWalletButtons(){document.querySelectorAll('[data-open="wallet"]').forEach(button=>{if(connectedWallet){button.innerHTML='<img class="wallet-brand-icon" src="assets/model-logos/'+connectedWallet.kind+'-wallet.svg" alt="" aria-hidden="true"><span>'+escapeHtml(connectedWallet.address.slice(0,4)+'…'+connectedWallet.address.slice(-4))+'</span>';button.title=connectedWallet.config.name+' · '+connectedWallet.address;}else{button.innerHTML='<img class="wallet-brand-icon" src="assets/model-logos/phantom-wallet.svg" alt="" aria-hidden="true"><span>Connect wallet</span>';button.removeAttribute('title');}});window.dispatchEvent(new CustomEvent('parallax-wallet-change',{detail:{address:connectedWallet?.address||null}}));}
function showWalletStatus(message,error=false){const el=document.querySelector('#wallet-status');if(el){el.textContent=message;el.classList.toggle('wallet-error',error);}}
async function requestWallet(kind){const config=walletProviders[kind];const provider=config?.get();if(!provider){showWalletStatus('Open this localhost URL in a desktop browser with the '+config.name+' extension installed Wallet extensions may not be available in this in-app browser',true);document.querySelector('#wallet-install').innerHTML='<a class="button" href="'+config.site+'" target="_blank" rel="noopener">Get '+config.name+'</a>';return;}const buttons=[...document.querySelectorAll('[data-wallet-provider]')];buttons.forEach(b=>b.disabled=true);showWalletStatus('Approve the connection in '+config.name+'.');try{const response=await provider.connect();const address=(response?.publicKey||provider.publicKey)?.toString();if(!address)throw new Error('No account returned');if(connectedWallet)detachWalletEvents();connectedWallet={kind,config,provider,address};connectedWallet.accountChanged=publicKey=>{if(!publicKey){detachWalletEvents();connectedWallet=null;}else if(connectedWallet){connectedWallet.address=publicKey.toString();}updateWalletButtons();if(document.querySelector('#info-dialog').open&&document.querySelector('#wallet-status'))openWalletContents();};connectedWallet.disconnected=()=>{detachWalletEvents();connectedWallet=null;updateWalletButtons();if(document.querySelector('#info-dialog').open&&document.querySelector('#wallet-status'))openWalletContents();};provider.on?.('accountChanged',connectedWallet.accountChanged);provider.on?.('disconnect',connectedWallet.disconnected);updateWalletButtons();openWalletContents();}catch(error){const rejected=error?.code===4001||/reject|cancel|declin/i.test(error?.message||'');showWalletStatus(rejected?'Connection cancelled. You can try again whenever you’re ready.':'The wallet could not connect. Unlock it, select an account, and try again.',true);}finally{buttons.forEach(b=>b.disabled=false);}}
function detachWalletEvents(){if(!connectedWallet)return;const w=connectedWallet;w.provider.removeListener?.('accountChanged',w.accountChanged);w.provider.removeListener?.('disconnect',w.disconnected);}
async function disconnectWallet(){if(!connectedWallet)return;const w=connectedWallet;try{await w.provider.disconnect();detachWalletEvents();connectedWallet=null;updateWalletButtons();openWalletContents();}catch{showWalletStatus('Disconnect was not completed. Try again or disconnect from your wallet settings.',true);}}
function openWalletContents(){const content=document.querySelector('#info-body');document.querySelector('#info-kicker').textContent='PARALLAX / SOLANA WALLET';if(connectedWallet){const w=connectedWallet;content.innerHTML='<div class="success-mark">✓</div><h2>Wallet connected.</h2><p>Connected through '+w.config.name+'.</p><div class="wallet-address"><span>SOLANA ADDRESS</span><code>'+escapeHtml(w.address)+'</code><button id="copy-wallet" class="text-button">Copy address</button></div><div class="dialog-note">Connection shares your public address only To launch a devnet agent, you separately approve a sign-in message and a testnet transaction No mainnet payments are requested</div><div id="wallet-status" role="status"></div><button class="button" id="disconnect-wallet">Disconnect wallet</button>';document.querySelector('#disconnect-wallet').onclick=disconnectWallet;document.querySelector('#copy-wallet').onclick=async()=>{try{await navigator.clipboard.writeText(w.address);showWalletStatus('Address copied.');}catch{showWalletStatus('Select the address above and copy it manually.');}};return;}content.innerHTML='<h2>Connect your wallet.</h2><p>Choose your Solana wallet to connect to Parallax.</p><div class="wallet-options">'+Object.entries(walletProviders).map(([kind,c])=>'<button class="wallet-option" data-wallet-provider="'+kind+'"><span class="wallet-mark '+kind+'">'+`<img src="assets/model-logos/${kind}-wallet.svg" alt="">`+'</span><span><b>'+c.name+'</b><small>'+ (c.get()?'Detected in this browser':'Connect extension or mobile wallet')+'</small></span><span class="wallet-choice-indicator">+</span></button>').join('')+'</div><div id="wallet-status" role="status">Your wallet will ask you to approve this connection.</div><div id="wallet-install"></div><div class="wallet-permission-note">Connecting shares your public address only Launching an agent asks separately for a sign-in message and a Solana devnet transaction Never enter a seed phrase</div>';document.querySelectorAll('[data-wallet-provider]').forEach(b=>b.onclick=()=>requestWallet(b.dataset.walletProvider));}
openWallet=function(){openWalletContents();document.querySelector('#info-dialog').showModal();};
